          "id": "code-ml-20-1-ch20_1_scratch",
          "title": "First-Principles NumPy/SciPy: Kernel PCA Double-Centering + Out-of-Sample & Isomap Geodesic Swiss Roll",
          "language": "python",
          "filename": "20_1_kpca_isomap_geodesic_scratch.py",
          "code": "import numpy as np\nfrom scipy.sparse import csr_matrix\nfrom scipy.sparse.csgraph import connected_components, dijkstra\nfrom scipy.spatial.distance import cdist\nfrom scipy.stats import spearmanr\n\nrng = np.random.default_rng(2011)\n\n# 1) Kernel PCA (RBF) dari Nol: Double-Centering Gram + Out-of-Sample Transform\ndef make_concentric(n_per_ring: int, r_in: float, r_out: float, noise: float):\n    th1 = rng.uniform(0.0, 2.0 * np.pi, n_per_ring)\n    th2 = rng.uniform(0.0, 2.0 * np.pi, n_per_ring)\n    X1 = np.column_stack([r_in * np.cos(th1), r_in * np.sin(th1)]) + rng.normal(0.0, noise, (n_per_ring, 2))\n    X2 = np.column_stack([r_out * np.cos(th2), r_out * np.sin(th2)]) + rng.normal(0.0, noise, (n_per_ring, 2))\n    X = np.vstack([X1, X2])\n    y = np.concatenate([np.zeros(n_per_ring, dtype=int), np.ones(n_per_ring, dtype=int)])\n    return X, y\n\nX_tr, y_tr = make_concentric(90, 0.9, 2.8, 0.14)\nX_te, y_te = make_concentric(45, 0.9, 2.8, 0.14)\nn_tr = X_tr.shape[0]\ngamma = 0.55\n\n# Matriks Gram latih K_tr & pemusatan ganda K_tilde = K - 1_n K - K 1_n + 1_n K 1_n\nK_tr = np.exp(-gamma * cdist(X_tr, X_tr, metric=\"sqeuclidean\"))\ncol_mean_tr = K_tr.mean(axis=0, keepdims=True)\nrow_mean_tr = K_tr.mean(axis=1, keepdims=True)\ngrand_mean_tr = float(K_tr.mean())\nK_tilde = K_tr - row_mean_tr - col_mean_tr + grand_mean_tr\n\neigvals, eigvecs = np.linalg.eigh(K_tilde)\nidx_desc = np.argsort(eigvals)[::-1]\neigvals = eigvals[idx_desc]\neigvecs = eigvecs[:, idx_desc]\n\n# Normalisasi eigenvector di RKHS: lam_m * ||alpha_m||^2 = 1\nlam3 = eigvals[:3]\nalpha3 = eigvecs[:, :3] / np.sqrt(np.maximum(lam3, 1e-12))[None, :]\nZ_tr_kpca = K_tilde @ alpha3\n\n# Proyeksi Out-of-Sample Eksak untuk X_te terhadap statistik latih!\nK_te = np.exp(-gamma * cdist(X_te, X_tr, metric=\"sqeuclidean\"))\nK_te_tilde = K_te - K_te.mean(axis=1, keepdims=True) - col_mean_tr + grand_mean_tr\nZ_te_kpca = K_te_tilde @ alpha3\n\n# Uji pemisahan linier 1D pada komponen pertama (PCA linier vs Kernel PCA)\nX_tr_c = X_tr - X_tr.mean(axis=0, keepdims=True)\n_, _, Vt_lin = np.linalg.svd(X_tr_c, full_matrices=False)\nz1_tr_lin = X_tr_c @ Vt_lin[0]\nz1_te_lin = (X_te - X_tr.mean(axis=0, keepdims=True)) @ Vt_lin[0]\n\ndef best_1d_thresh_acc(z_tr, y_t, z_te, y_e):\n    c0, c1 = z_tr[y_t == 0].mean(), z_tr[y_t == 1].mean()\n    thr = 0.5 * (c0 + c1)\n    pred = (z_te > thr).astype(int) if c1 >= c0 else (z_te < thr).astype(int)\n    return float(np.mean(pred == y_e))\n\nacc_lin = best_1d_thresh_acc(z1_tr_lin, y_tr, z1_te_lin, y_te)\nacc_kpca = best_1d_thresh_acc(Z_tr_kpca[:, 0], y_tr, Z_te_kpca[:, 0], y_te)\n\nprint(\"=== 1. Kernel PCA (RBF) From Scratch: Double-Centering & Out-of-Sample ===\")\nprint(f\"Verifikasi Centering | max|mean baris K_tilde| = {np.max(np.abs(K_tilde.mean(axis=1))):.2e}\")\nprint(f\"Top-3 Eigenvalue Gram Terpusat                 = [{lam3[0]:.4f}, {lam3[1]:.4f}, {lam3[2]:.4f}]\")\nprint(f\"Out-of-Sample 1D Threshold Acc | PCA Linier    = {acc_lin:.4f} (gagal pisah lingkaran!)\")\nprint(f\"Out-of-Sample 1D Threshold Acc | Kernel PCA    = {acc_kpca:.4f} (terpisah linier pada PC1 RKHS!)\")\n\n# 2) Isomap dari Nol pada Swiss Roll 3D: Graf k-NN -> Dijkstra Geodesic -> cMDS\nn_roll = 260\nt_roll = 1.5 * np.pi * (1.0 + 2.0 * rng.uniform(0.0, 1.0, n_roll))\nh_roll = 6.0 * rng.uniform(0.0, 1.0, n_roll)\nX_roll = np.column_stack([t_roll * np.cos(t_roll), h_roll, t_roll * np.sin(t_roll)])\n\nD_euc = cdist(X_roll, X_roll, metric=\"euclidean\")\nk_nn = 8\nrows, cols, weights = [], [], []\nfor i in range(n_roll):\n    nn_idx = np.argsort(D_euc[i])[1 : k_nn + 1]\n    for j in nn_idx:\n        rows.extend([i, j])\n        cols.extend([j, i])\n        weights.extend([D_euc[i, j], D_euc[i, j]])\n\nG_knn = csr_matrix((weights, (rows, cols)), shape=(n_roll, n_roll))\nn_comp, _ = connected_components(G_knn, directed=False)\nD_geo = dijkstra(G_knn, directed=False)\n\n# Classical MDS atas D_geo^2: B = -0.5 * H * D_geo^2 * H\nD2 = D_geo ** 2\nH = np.eye(n_roll) - np.ones((n_roll, n_roll)) / n_roll\nB = -0.5 * (H @ D2 @ H)\nev_b, evec_b = np.linalg.eigh(B)\ntop2 = np.argsort(ev_b)[::-1][:2]\nZ_iso = evec_b[:, top2] * np.sqrt(np.maximum(ev_b[top2], 0.0))[None, :]\n\n# Bandingkan terhadap PCA Linier pada Swiss Roll\nXc_roll = X_roll - X_roll.mean(axis=0, keepdims=True)\n_, _, Vt_r = np.linalg.svd(Xc_roll, full_matrices=False)\nZ_pca_r = Xc_roll @ Vt_r[:2].T\n\nrho_pca = max(abs(float(spearmanr(t_roll, Z_pca_r[:, 0]).statistic)),\n              abs(float(spearmanr(t_roll, Z_pca_r[:, 1]).statistic)))\nrho_iso = max(abs(float(spearmanr(t_roll, Z_iso[:, 0]).statistic)),\n              abs(float(spearmanr(t_roll, Z_iso[:, 1]).statistic)))\n\n# Ambil pasangan pada lapisan spiral berbeda (|t_i - t_j| > 5.5) tetapi dekat secara Euclidean\nmask_cross = np.abs(t_roll[:, None] - t_roll[None, :]) > 5.5\ncross_euc = np.where(mask_cross, D_euc, np.inf)\ni_p, j_p = np.unravel_index(np.argmin(cross_euc), cross_euc.shape)\n\nprint(\"\\n=== 2. Isomap From Scratch pada Swiss Roll 3D (k=8, n=260) ===\")\nprint(f\"Jumlah Komponen Graf k-NN      = {n_comp} (terhubung penuh)\")\nprint(f\"Pasangan Lintas-Lapisan Spiral | Jarak Euclidean = {D_euc[i_p, j_p]:.3f} vs Geodesik = {D_geo[i_p, j_p]:.3f} ({D_geo[i_p, j_p]/D_euc[i_p, j_p]:.2f}x!)\")\nprint(f\"Pemulihan Posisi Intrinsik t   | |Spearman| PCA = {rho_pca:.4f} vs Isomap = {rho_iso:.4f}\")",
          "expectedOutput": "=== 1. Kernel PCA (RBF) From Scratch: Double-Centering & Out-of-Sample ===\nVerifikasi Centering | max|mean baris K_tilde| = 7.89e-17\nTop-3 Eigenvalue Gram Terpusat                 = [26.0286, 20.3271, 16.8729]\nOut-of-Sample 1D Threshold Acc | PCA Linier    = 0.6333 (gagal pisah lingkaran!)\nOut-of-Sample 1D Threshold Acc | Kernel PCA    = 1.0000 (terpisah linier pada PC1 RKHS!)\n\n=== 2. Isomap From Scratch pada Swiss Roll 3D (k=8, n=260) ===\nJumlah Komponen Graf k-NN      = 1 (terhubung penuh)\nPasangan Lintas-Lapisan Spiral | Jarak Euclidean = 6.226 vs Geodesik = 59.598 (9.57x!)\nPemulihan Posisi Intrinsik t   | |Spearman| PCA = 0.2885 vs Isomap = 0.9993",
