          "code": "import numpy as np\nfrom scipy.stats import spearmanr\nfrom sklearn.datasets import make_circles, make_swiss_roll\nfrom sklearn.decomposition import KernelPCA, PCA\nfrom sklearn.kernel_approximation import Nystroem\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.manifold import Isomap\nfrom sklearn.model_selection import StratifiedKFold, cross_val_score\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\n\n# 1) Benchmark Unfolding Swiss Roll 3D: PCA vs KernelPCA vs Nystroem+PCA vs Isomap\nX_roll, t_roll = make_swiss_roll(n_samples=360, noise=0.05, random_state=42)\nX_roll[:, 1] *= 0.35  # Pita Swiss Roll rapat agar graf k-NN menelusuri permukaan mulus\n\nroll_models = [\n    (\"PCA (Linier)\", PCA(n_components=2, random_state=42)),\n    (\"KernelPCA (RBF, gamma=0.015)\", KernelPCA(n_components=2, kernel=\"rbf\", gamma=0.015, random_state=42)),\n    (\"Nystroem(100)+PCA (Aproksimasi)\", Pipeline([\n        (\"nys\", Nystroem(kernel=\"rbf\", gamma=0.015, n_components=100, random_state=42)),\n        (\"pca\", PCA(n_components=2, random_state=42)),\n    ])),\n    (\"Isomap (k=8, Geodesik)\", Isomap(n_neighbors=8, n_components=2)),\n]\n\nprint(\"=== 1. Benchmark Unfolding Swiss Roll 3D (n=360) ===\")\nprint(\"Metode                          | |Spearman(t, z_best)| | Kemampuan Unfold\")\nprint(\"-\" * 76)\nfor name, model in roll_models:\n    Z = model.fit_transform(X_roll)\n    rho_best = max(abs(float(spearmanr(t_roll, Z[:, 0]).statistic)),\n                   abs(float(spearmanr(t_roll, Z[:, 1]).statistic)))\n    verdict = \"Membuka manifold mulus\" if rho_best > 0.95 else (\"Melengkung parsial\" if rho_best > 0.65 else \"Tumpang-tindih linier\")\n    print(f\"{name:31s} | {rho_best:21.4f} | {verdict}\")\n\n# 2) Benchmark Out-of-Sample Classification (5-Fold CV) pada Lingkaran Konsentris Non-Linier\nX_circ, y_circ = make_circles(n_samples=360, factor=0.38, noise=0.07, random_state=42)\ncv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\n\npipelines = [\n    (\"StandardScaler + PCA(2) + LogReg\", Pipeline([\n        (\"sc\", StandardScaler()),\n        (\"red\", PCA(n_components=2)),\n        (\"clf\", LogisticRegression(max_iter=500)),\n    ])),\n    (\"StandardScaler + KernelPCA(RBF,3) + LogReg\", Pipeline([\n        (\"sc\", StandardScaler()),\n        (\"red\", KernelPCA(n_components=3, kernel=\"rbf\", gamma=1.2, random_state=42)),\n        (\"clf\", LogisticRegression(max_iter=500)),\n    ])),\n    (\"StandardScaler + Nystroem(60)+PCA(3) + LogReg\", Pipeline([\n        (\"sc\", StandardScaler()),\n        (\"nys\", Nystroem(kernel=\"rbf\", gamma=1.2, n_components=60, random_state=42)),\n        (\"red\", PCA(n_components=3, random_state=42)),\n        (\"clf\", LogisticRegression(max_iter=500)),\n    ])),\n    (\"StandardScaler + Isomap(k=12,3) + LogReg\", Pipeline([\n        (\"sc\", StandardScaler()),\n        (\"red\", Isomap(n_neighbors=12, n_components=3)),\n        (\"clf\", LogisticRegression(max_iter=500)),\n    ])),\n]\n\nprint(\"\\n=== 2. Out-of-Sample 5-Fold CV Accuracy pada Lingkaran Konsentris (n=360) ===\")\nfor name, pipe in pipelines:\n    scores = cross_val_score(pipe, X_circ, y_circ, cv=cv, scoring=\"accuracy\")\n    print(f\"{name:46s} | Mean Acc = {scores.mean():.4f} (+/- {scores.std():.4f})\")",
