          "title": "Production Audit: Isomap Topological Short-Circuiting (k & Noise Jembatan) & Sensitivitas Gamma Kernel PCA",
          "language": "python",
          "filename": "20_1_isomap_shortcircuit_kpca_gamma_audit.py",
          "code": "import numpy as np\nfrom scipy.sparse.csgraph import connected_components\nfrom scipy.spatial.distance import cdist\nfrom scipy.stats import spearmanr\nfrom sklearn.datasets import make_circles, make_swiss_roll\nfrom sklearn.decomposition import KernelPCA\nfrom sklearn.manifold import Isomap\nfrom sklearn.neighbors import kneighbors_graph\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(2013)\n\n# 1) Audit Topological Short-Circuiting pada Isomap: Efek k Terlalu Besar & 8 Titik Noise Jembatan\nX_clean, t_clean = make_swiss_roll(n_samples=320, noise=0.05, random_state=42)\nX_clean[:, 1] *= 0.30  # Pita rapat agar k=7 menelusuri manifold tanpa shortcut\n\n# Suntikkan 10 titik jembatan berderet melintasi celah udara antar lapisan spiral (sudut ~1.2 rad)\nth_b = rng.uniform(0.9, 1.5, 10)\nr_b = np.linspace(5.8, 12.2, 10)\nh_b = rng.uniform(1.5, 4.5, 10)\nX_bridge = np.column_stack([r_b * np.cos(th_b), h_b, r_b * np.sin(th_b)])\nX_noisy = np.vstack([X_clean, X_bridge])\n\ndef audit_isomap_case(label: str, X_in: np.ndarray, t_ref: np.ndarray, k: int):\n    n_clean = len(t_ref)\n    G = kneighbors_graph(X_in, n_neighbors=k, mode=\"distance\", include_self=False)\n    G_sym = G.maximum(G.T)\n    n_cc, _ = connected_components(G_sym, directed=False)\n    # Hitung tepi shortcut lintas lapisan pada titik bersih atau lewat jembatan (|t_i - t_j| > pi)\n    rows, cols = G_sym.nonzero()\n    cross_edges = sum(\n        1 for i, j in zip(rows, cols)\n        if i < j and i < n_clean and j < n_clean and abs(t_ref[i] - t_ref[j]) > np.pi\n    )\n    bridge_edges = sum(1 for i, j in zip(rows, cols) if i < j and (i >= n_clean or j >= n_clean))\n    iso = Isomap(n_neighbors=k, n_components=2).fit(X_in)\n    Z_clean = iso.embedding_[:n_clean]\n    rho = max(abs(float(spearmanr(t_ref, Z_clean[:, 0]).statistic)),\n              abs(float(spearmanr(t_ref, Z_clean[:, 1]).statistic)))\n    print(f\"{label:36s} | k={k:2d} | Comp={n_cc} | Cross={cross_edges:4d} | Bridge={bridge_edges:2d} | |Spearman(t)|={rho:.4f}\")\n\nprint(\"=== 1. Audit Kegagalan Isomap: Disconnected vs Sehat vs Short-Circuiting ===\")\naudit_isomap_case(\"Bersih (k terlalu kecil -> putus)\", X_clean, t_clean, k=2)\naudit_isomap_case(\"Bersih (k optimal lokal)\", X_clean, t_clean, k=7)\naudit_isomap_case(\"Bersih (k terlalu besar -> bocor!)\", X_clean, t_clean, k=35)\naudit_isomap_case(\"+ 10 Titik Noise Jembatan (k=7)\", X_noisy, t_clean, k=7)\n\n# 2) Audit Sensitivitas Gamma pada KernelPCA RBF (Under-kernel vs Optimal vs Gram -> Identitas)\nX_c, y_c = make_circles(n_samples=240, factor=0.4, noise=0.06, random_state=42)\nX_cs = StandardScaler().fit_transform(X_c)\nX_tr, X_te = X_cs[:180], X_cs[180:]\n\nprint(\"\\n=== 2. Audit Sensitivitas Gamma pada KernelPCA RBF (Standardized Circles) ===\")\nprint(\"Gamma    | Mean Off-Diag K | lam_1 / lam_10 | Mean ||Z_test|| | Diagnosa\")\nprint(\"-\" * 78)\nfor g in [1e-4, 1.0, 50.0]:\n    K = np.exp(-g * cdist(X_tr, X_tr, metric=\"sqeuclidean\"))\n    off_mean = float((K.sum() - np.trace(K)) / (K.size - len(K)))\n    kpca = KernelPCA(n_components=10, kernel=\"rbf\", gamma=g, random_state=42).fit(X_tr)\n    lam_ratio = float(kpca.eigenvalues_[0] / max(kpca.eigenvalues_[9], 1e-12))\n    z_te_norm = float(np.mean(np.linalg.norm(kpca.transform(X_te)[:, :2], axis=1)))\n    if g < 1e-2:\n        diag = \"Terlalu kecil -> kolaps ke PCA linier\"\n    elif g > 10.0:\n        diag = \"Terlalu besar -> K ~ I, titik terisolasi!\"\n    else:\n        diag = \"Optimal (mendekati median heuristic)\"\n    print(f\"{g:8.4f} | {off_mean:15.4f} | {lam_ratio:14.2f} | {z_te_norm:15.4f} | {diag}\")",
          "expectedOutput": "=== 1. Audit Kegagalan Isomap: Disconnected vs Sehat vs Short-Circuiting ===\nBersih (k terlalu kecil -> putus)    | k= 2 | Comp=22 | Cross=   0 | Bridge= 0 | |Spearman(t)|=0.1774\nBersih (k optimal lokal)             | k= 7 | Comp=1 | Cross=   0 | Bridge= 0 | |Spearman(t)|=0.9997\nBersih (k terlalu besar -> bocor!)   | k=35 | Comp=1 | Cross= 556 | Bridge= 0 | |Spearman(t)|=0.2078\n+ 10 Titik Noise Jembatan (k=7)      | k= 7 | Comp=1 | Cross=   0 | Bridge=70 | |Spearman(t)|=0.7252\n\n=== 2. Audit Sensitivitas Gamma pada KernelPCA RBF (Standardized Circles) ===\nGamma    | Mean Off-Diag K | lam_1 / lam_10 | Mean ||Z_test|| | Diagnosa\n------------------------------------------------------------------------------\n  0.0001 |          0.9996 | 38093215266.49 |          0.0177 | Terlalu kecil -> kolaps ke PCA linier\n  1.0000 |          0.1782 |           5.45 |          0.4669 | Optimal (mendekati median heuristic)\n 50.0000 |          0.0081 |           1.51 |          0.0853 | Terlalu besar -> K ~ I, titik terisolasi!",
