          "solution": "```python\nimport numpy as np\nfrom scipy.sparse import csr_matrix\nfrom scipy.sparse.csgraph import dijkstra\nfrom scipy.spatial.distance import cdist\n\ndef centered_rbf_kpca_and_geodesic(X, gamma: float = 0.02, k_nn: int = 6) -> tuple[float, float, float]:\n    X = np.asarray(X, dtype=float)\n    n = X.shape[0]\n    D_euc = cdist(X, X, metric=\"euclidean\")\n    K = np.exp(-gamma * (D_euc ** 2))\n    K_tilde = K - K.mean(axis=1, keepdims=True) - K.mean(axis=0, keepdims=True) + float(K.mean())\n    center_err = float(np.max(np.abs(K_tilde.mean(axis=1))))\n    eigs = np.linalg.eigvalsh(K_tilde)[::-1]\n    pos = eigs[eigs > 1e-10]\n    top2_ratio = float(np.sum(pos[:2]) / np.sum(pos))\n    rows, cols, weights = [], [], []\n    for i in range(n):\n        nn = np.argsort(D_euc[i])[1 : k_nn + 1]\n        for j in nn:\n            rows.extend([i, j]); cols.extend([j, i]); weights.extend([D_euc[i, j], D_euc[i, j]])\n    G = csr_matrix((weights, (rows, cols)), shape=(n, n))\n    D_geo = dijkstra(G, directed=False)\n    iu = np.triu_indices(n, k=1)\n    geo_euc_ratio = float(np.mean(D_geo[iu]) / np.mean(D_euc[iu]))\n    return (round(center_err, 8), round(top2_ratio, 4), round(geo_euc_ratio, 4))\n```"
