          "code": "import numpy as np\nfrom sklearn.manifold import TSNE\n\nrng = np.random.default_rng(2022)\n\n# Eksperimen Wattenberg et al.: 3 klaster dengan rasio radius 10x & rasio jarak antar-klaster 4x!\nn_c = 70\nd = 8\nmu_A = np.zeros(d)\nmu_B = np.zeros(d); mu_B[0] = 12.0   # d(A, B) = 12\nmu_C = np.zeros(d); mu_C[0] = 60.0   # d(B, C) = 48 -> rasio sejati d(B,C)/d(A,B) = 4.00x!\n\nX_A = rng.normal(mu_A, 0.30, size=(n_c, d))  # Klaster A sangat rapat (sigma = 0.30)\nX_B = rng.normal(mu_B, 3.00, size=(n_c, d))  # Klaster B 10x lebih lebar (sigma = 3.00)!\nX_C = rng.normal(mu_C, 0.90, size=(n_c, d))\nX = np.vstack([X_A, X_B, X_C])\ny = np.repeat([0, 1, 2], n_c)\n\ndef cluster_geometry(Z: np.ndarray, lbl: np.ndarray):\n    means = [Z[lbl == c].mean(axis=0) for c in range(3)]\n    radii = [float(np.mean(np.linalg.norm(Z[lbl == c] - means[c], axis=1))) for c in range(3)]\n    d_ab = float(np.linalg.norm(means[1] - means[0]))\n    d_bc = float(np.linalg.norm(means[2] - means[1]))\n    return radii[1] / max(radii[0], 1e-9), d_bc / max(d_ab, 1e-9)\n\ntrue_rad_ratio, true_dist_ratio = cluster_geometry(X, y)\n\nprint(\"=== Bukti Kuantitatif Jebakan Wattenberg pada Scikit-Learn TSNE ===\")\nprint(f\"Ruang Asli (R^8)       | Rasio Radius R_B/R_A = {true_rad_ratio:6.2f}x | Rasio Jarak d_BC/d_AB = {true_dist_ratio:5.2f}x\")\nprint(\"-\" * 82)\nprint(\"Setting TSNE           | Rasio Radius R_B/R_A | Rasio Jarak d_BC/d_AB | Distorsi!\")\nprint(\"-\" * 82)\n\nfor perp in [5.0, 20.0, 45.0, 75.0]:\n    Z = TSNE(\n        n_components=2,\n        perplexity=perp,\n        init=\"pca\",\n        learning_rate=\"auto\",\n        max_iter=500,\n        random_state=42,\n    ).fit_transform(X)\n    r_rat, d_rat = cluster_geometry(Z, y)\n    note = \"Ukuran & jarak terdistorsi!\"\n    print(f\"perplexity={perp:4.1f}        | {r_rat:19.2f}x | {d_rat:20.2f}x | {note}\")",
          "expectedOutput": "=== Bukti Kuantitatif Jebakan Wattenberg pada Scikit-Learn TSNE ===\nRuang Asli (R^8)       | Rasio Radius R_B/R_A =   9.88x | Rasio Jarak d_BC/d_AB =  3.86x\n----------------------------------------------------------------------------------\nSetting TSNE           | Rasio Radius R_B/R_A | Rasio Jarak d_BC/d_AB | Distorsi!\n----------------------------------------------------------------------------------\nperplexity= 5.0        |                0.97x |                 1.01x | Ukuran & jarak terdistorsi!\nperplexity=20.0        |                1.08x |                 1.12x | Ukuran & jarak terdistorsi!\nperplexity=45.0        |                1.22x |                 2.16x | Ukuran & jarak terdistorsi!\nperplexity=75.0        |                2.24x |                 3.75x | Ukuran & jarak terdistorsi!",
