          "filename": "20_2_tsne_transductive_leakage_audit.py",
          "code": "import numpy as np\nfrom scipy.spatial.distance import pdist\nfrom scipy.stats import spearmanr\nfrom sklearn.datasets import make_circles\nfrom sklearn.decomposition import KernelPCA, PCA\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.manifold import TSNE\nfrom sklearn.model_selection import StratifiedKFold, cross_val_score\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(2023)\n\n# 1) Audit Transductive Leakage & Ketiadaan .transform() pada t-SNE vs Inductive Pipeline\nX_2d, y = make_circles(n_samples=280, factor=0.38, noise=0.07, random_state=42)\nX_noise = rng.normal(0.0, 0.20, size=(280, 2))\nX = np.hstack([X_2d, X_noise])\ncv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\n\n# ANTI-PATTERN: TSNE().fit_transform(X_all) lalu CV klasifikasi -> bocor + tak bisa serve data baru!\nZ_tsne_leaky = TSNE(n_components=2, perplexity=25, init=\"pca\", learning_rate=\"auto\", max_iter=450, random_state=42).fit_transform(X)\nauc_leaky_tsne = float(np.mean(cross_val_score(LogisticRegression(), Z_tsne_leaky, y, cv=cv, scoring=\"roc_auc\")))\n\n# PRODUCTION-SAFE: Inductive Pipeline yang mendukung .transform() pada data baru!\npipe_pca = Pipeline([(\"sc\", StandardScaler()), (\"pca\", PCA(n_components=3)), (\"clf\", LogisticRegression())])\npipe_kpca = Pipeline([(\"sc\", StandardScaler()), (\"kpca\", KernelPCA(n_components=6, kernel=\"rbf\", gamma=0.5, random_state=42)), (\"clf\", LogisticRegression())])\nauc_pca = float(np.mean(cross_val_score(pipe_pca, X, y, cv=cv, scoring=\"roc_auc\")))\nauc_kpca = float(np.mean(cross_val_score(pipe_kpca, X, y, cv=cv, scoring=\"roc_auc\")))\n\n# Buktikan kegagalan produksi jika mencoba memanggil .transform() pada TSNE\nhas_transform = hasattr(TSNE(), \"transform\")\npipe_kpca.fit(X[:220], y[:220])\nsingle_tx_proba = float(pipe_kpca.predict_proba(X[220:221])[0, 1])\n\nprint(\"=== 1. Audit Transductive Anti-Pattern t-SNE vs Inductive Production Pipeline ===\")\nprint(f\"Apakah TSNE memiliki metode .transform()?          = {has_transform}  <-- MUSTAHIL untuk online serving!\")\nprint(f\"5-Fold AUROC | ANTI-PATTERN TSNE.fit_transform(all)= {auc_leaky_tsne:.4f} (bocor transduktif & tak bisa deploy!)\")\nprint(f\"5-Fold AUROC | Pipeline(Scaler + PCA + LogReg)     = {auc_pca:.4f} (induktif, tapi linier gagal pada lingkaran)\")\nprint(f\"5-Fold AUROC | Pipeline(Scaler + KernelPCA + LR)   = {auc_kpca:.4f} (induktif, bebas bocor, serve p={single_tx_proba:.3f})\")\n\n# 2) Audit Stabilitas Global Antar-Seed: init='random' vs init='pca'\ncenters = np.array([\n    [0, 0, 0, 0], [8, 0, 0, 0], [20, 4, 0, 0], [4, 18, 0, 0], [28, 22, 0, 0]\n], dtype=float)\nX_cl = np.vstack([rng.normal(c, 0.9, size=(32, 4)) for c in centers])\ny_cl = np.repeat(np.arange(5), 32)\ntrue_cdist = pdist(centers)\n\ndef eval_init_stability(init_mode: str):\n    rhos = []\n    for seed in [10, 20, 30, 40]:\n        Z = TSNE(n_components=2, perplexity=20, init=init_mode, learning_rate=\"auto\", max_iter=350, random_state=seed).fit_transform(X_cl)\n        z_centers = np.array([Z[y_cl == c].mean(axis=0) for c in range(5)])\n        rhos.append(float(spearmanr(true_cdist, pdist(z_centers)).statistic))\n    return float(np.mean(rhos)), float(np.std(rhos))\n\nm_rand, s_rand = eval_init_stability(\"random\")\nm_pca, s_pca = eval_init_stability(\"pca\")\nprint(\"\\n=== 2. Stabilitas Geometri Antar-Klaster (4 Seed): init='random' vs init='pca' ===\")\nprint(f\"init='random' | Mean Global Centroid Spearman = {m_rand:+.4f} | Std antar-seed = {s_rand:.4f} (liar!)\")\nprint(f\"init='pca'    | Mean Global Centroid Spearman = {m_pca:+.4f} | Std antar-seed = {s_pca:.4f} (stabil!)\")",
          "expectedOutput": "=== 1. Audit Transductive Anti-Pattern t-SNE vs Inductive Production Pipeline ===\nApakah TSNE memiliki metode .transform()?          = False  <-- MUSTAHIL untuk online serving!\n5-Fold AUROC | ANTI-PATTERN TSNE.fit_transform(all)= 0.4954 (bocor transduktif & tak bisa deploy!)\n5-Fold AUROC | Pipeline(Scaler + PCA + LogReg)     = 0.3783 (induktif, tapi linier gagal pada lingkaran)\n5-Fold AUROC | Pipeline(Scaler + KernelPCA + LR)   = 0.9339 (induktif, bebas bocor, serve p=0.337)\n\n=== 2. Stabilitas Geometri Antar-Klaster (4 Seed): init='random' vs init='pca' ===\ninit='random' | Mean Global Centroid Spearman = +0.0593 | Std antar-seed = 0.4066 (liar!)\ninit='pca'    | Mean Global Centroid Spearman = +0.3283 | Std antar-seed = 0.0000 (stabil!)",
          "actualOutput": "=== 1. Audit Transductive Anti-Pattern t-SNE vs Inductive Production Pipeline ===\nApakah TSNE memiliki metode .transform()?          = False  <-- MUSTAHIL untuk online serving!\n5-Fold AUROC | ANTI-PATTERN TSNE.fit_transform(all)= 0.4954 (bocor transduktif & tak bisa deploy!)\n5-Fold AUROC | Pipeline(Scaler + PCA + LogReg)     = 0.3783 (induktif, tapi linier gagal pada lingkaran)\n5-Fold AUROC | Pipeline(Scaler + KernelPCA + LR)   = 0.9339 (induktif, bebas bocor, serve p=0.337)\n\n=== 2. Stabilitas Geometri Antar-Klaster (4 Seed): init='random' vs init='pca' ===\ninit='random' | Mean Global Centroid Spearman = +0.0593 | Std antar-seed = 0.4066 (liar!)\ninit='pca'    | Mean Global Centroid Spearman = +0.3283 | Std antar-seed = 0.0000 (stabil!)",
