          "code": "import numpy as np\nfrom scipy.spatial.distance import cdist, pdist\nfrom scipy.stats import spearmanr\nfrom sklearn.decomposition import PCA\nfrom sklearn.manifold import SpectralEmbedding, TSNE, trustworthiness\n\nrng = np.random.default_rng(2032)\n\n# Manifold Hierarkis 3-Makro x 2-Subklaster di R^12 (Segitiga Makro Asimetris: jarak 14, 24, 34)\nn_sub = 30\ncenters = np.array([\n    [0.0, 0.0, 0.0] + [0.0] * 9,\n    [3.5, 0.0, 0.0] + [0.0] * 9,\n    [14.0, 2.0, 0.0] + [0.0] * 9,\n    [17.5, 2.0, 0.0] + [0.0] * 9,\n    [6.0, 26.0, 0.0] + [0.0] * 9,\n    [9.5, 26.0, 0.0] + [0.0] * 9,\n])\nX = np.vstack([rng.normal(c, 0.65, size=(n_sub, 12)) for c in centers])\nlbl = np.repeat(np.arange(6), n_sub)\nD_hi = cdist(X, X, metric=\"euclidean\")\nn = X.shape[0]\n\ndef pacmap_lite(D_mat: np.ndarray, seed: int = 42):\n    r = np.random.default_rng(seed)\n    n_p = D_mat.shape[0]\n    order = np.argsort(D_mat, axis=1)\n    sig = np.mean(np.take_along_axis(D_mat, order[:, 4:7], axis=1), axis=1) + 1e-8\n    D_sc = (D_mat ** 2) / (sig[:, None] * sig[None, :])\n    nb_i, nb_j, mn_i, mn_j, fp_i, fp_j = [], [], [], [], [], []\n    for i in range(n_p):\n        nns = np.argsort(D_sc[i])[1:9]\n        for j in nns:\n            nb_i.append(i); nb_j.append(int(j))\n        for _ in range(4):\n            cand = r.choice(n_p, size=6, replace=False)\n            cand = cand[cand != i]\n            mn_i.append(i); mn_j.append(int(cand[np.argsort(D_mat[i, cand])[1]]))\n        nn_s = set(nns.tolist()) | {i}\n        c_cnt = 0\n        while c_cnt < 12:\n            c = int(r.integers(0, n_p))\n            if c not in nn_s:\n                fp_i.append(i); fp_j.append(c); c_cnt += 1\n    nb_i, nb_j = np.array(nb_i), np.array(nb_j)\n    mn_i, mn_j = np.array(mn_i), np.array(mn_j)\n    fp_i, fp_j = np.array(fp_i), np.array(fp_j)\n    Y = PCA(n_components=2, random_state=seed).fit_transform(X)\n    Y = Y / (np.std(Y) + 1e-9) * 0.5\n    m, v = np.zeros_like(Y), np.zeros_like(Y)\n    for it in range(1, 221):\n        if it <= 70:\n            w_nb, w_mn, w_fp = 2.0, 1000.0 * (1.0 - (it - 1) / 70.0) + 3.0 * ((it - 1) / 70.0), 1.0\n        elif it <= 140:\n            w_nb, w_mn, w_fp = 3.0, 3.0, 1.0\n        else:\n            w_nb, w_mn, w_fp = 1.0, 0.0, 1.0\n        g = np.zeros_like(Y)\n        d1 = Y[nb_i] - Y[nb_j]; t1 = np.sum(d1 ** 2, axis=1) + 1.0\n        f1 = (2.0 * w_nb * 10.0 / ((10.0 + t1) ** 2))[:, None] * d1\n        np.add.at(g, nb_i, f1); np.add.at(g, nb_j, -f1)\n        if w_mn > 0:\n            d2 = Y[mn_i] - Y[mn_j]; t2 = np.sum(d2 ** 2, axis=1) + 1.0\n            f2 = (2.0 * w_mn * 10000.0 / ((10000.0 + t2) ** 2))[:, None] * d2\n            np.add.at(g, mn_i, f2); np.add.at(g, mn_j, -f2)\n        d3 = Y[fp_i] - Y[fp_j]; t3 = np.sum(d3 ** 2, axis=1) + 1.0\n        f3 = (-2.0 * w_fp / ((1.0 + t3) ** 2))[:, None] * d3\n        np.add.at(g, fp_i, f3); np.add.at(g, fp_j, -f3)\n        m = 0.9 * m + 0.1 * g\n        v = 0.999 * v + 0.001 * (g ** 2)\n        Y -= 0.5 * (m / (1.0 - 0.9 ** it)) / (np.sqrt(v / (1.0 - 0.999 ** it)) + 1e-7)\n        Y -= Y.mean(axis=0, keepdims=True)\n    return Y\n\nembeddings = [\n    (\"PCA (Linier Global)\", PCA(n_components=2, random_state=42).fit_transform(X)),\n    (\"SpectralEmbedding (Init UMAP)\", SpectralEmbedding(n_components=2, n_neighbors=12, random_state=42).fit_transform(X)),\n    (\"t-SNE (perp=15, init='random')\", TSNE(n_components=2, perplexity=15, init=\"random\", learning_rate=\"auto\", max_iter=450, random_state=42).fit_transform(X)),\n    (\"t-SNE (perp=25, init='pca')\", TSNE(n_components=2, perplexity=25, init=\"pca\", learning_rate=\"auto\", max_iter=450, random_state=42).fit_transform(X)),\n    (\"PaCMAP (3-Pair, 3-Phase)\", pacmap_lite(D_hi, seed=42)),\n]\n\nc_hi = np.array([X[lbl == c].mean(axis=0) for c in range(6)])\ntri_hi = pdist(X)\n\nprint(\"=== Benchmark Keseimbangan Lokal vs Global (Hierarki 3-Makro x 2-Subklaster di R^12) ===\")\nprint(\"Metode                         | Trust(10) | 10-NN Rec | Glob Centroid | Shepard Rho\")\nprint(\"-\" * 86)\nfor name, Y in embeddings:\n    trust = float(trustworthiness(X, Y, n_neighbors=10))\n    Dy = cdist(Y, Y, metric=\"euclidean\")\n    rec = float(np.mean([len(set(np.argsort(D_hi[i])[1:11]) & set(np.argsort(Dy[i])[1:11])) / 10.0 for i in range(n)]))\n    c_lo = np.array([Y[lbl == c].mean(axis=0) for c in range(6)])\n    glob = float(spearmanr(pdist(c_hi), pdist(c_lo)).statistic)\n    shep = float(spearmanr(tri_hi, pdist(Y)).statistic)\n    print(f\"{name:30s} | {trust:9.4f} | {rec:9.4f} | {glob:13.4f} | {shep:11.4f}\")",
