          "code": "import numpy as np\nfrom scipy.sparse.csgraph import connected_components\nfrom scipy.spatial.distance import cdist, pdist\nfrom scipy.stats import spearmanr\n\nrng = np.random.default_rng(2033)\n\n# 4 Klaster tersusun linier secara global (jarak 0, 10, 26, 48) di R^8\ncenters = np.array([[0.0], [10.0], [26.0], [48.0]]) * np.array([[1, 0, 0, 0, 0, 0, 0, 0]])\nn_c = 35\nX = np.vstack([rng.normal(c, 0.75, size=(n_c, 8)) for c in centers])\nlbl = np.repeat(np.arange(4), n_c)\nn = X.shape[0]\nD = cdist(X, X, metric=\"euclidean\")\n\n# 1) Ablasi 3-Fase PaCMAP dari Inisialisasi Acak Murni\ndef run_pacmap_ablation(mode: str, seed: int = 99):\n    r = np.random.default_rng(seed)\n    order = np.argsort(D, axis=1)\n    sig = np.mean(np.take_along_axis(D, order[:, 4:7], axis=1), axis=1) + 1e-8\n    D_sc = (D ** 2) / (sig[:, None] * sig[None, :])\n    nb_i, nb_j, mn_i, mn_j, fp_i, fp_j = [], [], [], [], [], []\n    for i in range(n):\n        nns = np.argsort(D_sc[i])[1:9]\n        for j in nns:\n            nb_i.append(i); nb_j.append(int(j))\n        for _ in range(6):\n            cand = r.choice(n, size=6, replace=False)\n            cand = cand[cand != i]\n            mn_i.append(i); mn_j.append(int(cand[np.argsort(D[i, cand])[1]]))\n        nn_s = set(nns.tolist()) | {i}\n        cnt = 0\n        while cnt < 12:\n            c = int(r.integers(0, n))\n            if c not in nn_s:\n                fp_i.append(i); fp_j.append(c); cnt += 1\n    nb_i, nb_j = np.array(nb_i), np.array(nb_j)\n    mn_i, mn_j = np.array(mn_i), np.array(mn_j)\n    fp_i, fp_j = np.array(fp_i), np.array(fp_j)\n\n    Y = r.normal(0.0, 0.5, size=(n, 2))\n    m, v = np.zeros_like(Y), np.zeros_like(Y)\n    for it in range(1, 241):\n        if mode == \"full_3phase\":\n            if it <= 90:\n                w_nb, w_mn, w_fp = 2.0, 1000.0 * (1.0 - (it - 1) / 90.0) + 3.0 * ((it - 1) / 90.0), 1.0\n            elif it <= 160:\n                w_nb, w_mn, w_fp = 3.0, 3.0, 1.0\n            else:\n                w_nb, w_mn, w_fp = 1.0, 0.0, 1.0\n        elif mode == \"no_mid_near\":\n            w_nb, w_mn, w_fp = 2.0, 0.0, 1.0\n        else:  # constant_mid_near: Mid-Near tidak pernah dimatikan!\n            w_nb, w_mn, w_fp = 1.0, 600.0, 1.0\n        g = np.zeros_like(Y)\n        d1 = Y[nb_i] - Y[nb_j]; t1 = np.sum(d1 ** 2, axis=1) + 1.0\n        f1 = (2.0 * w_nb * 10.0 / ((10.0 + t1) ** 2))[:, None] * d1\n        np.add.at(g, nb_i, f1); np.add.at(g, nb_j, -f1)\n        if w_mn > 0:\n            d2 = Y[mn_i] - Y[mn_j]; t2 = np.sum(d2 ** 2, axis=1) + 1.0\n            f2 = (2.0 * w_mn * 10000.0 / ((10000.0 + t2) ** 2))[:, None] * d2\n            np.add.at(g, mn_i, f2); np.add.at(g, mn_j, -f2)\n        d3 = Y[fp_i] - Y[fp_j]; t3 = np.sum(d3 ** 2, axis=1) + 1.0\n        f3 = (-2.0 * w_fp / ((1.0 + t3) ** 2))[:, None] * d3\n        np.add.at(g, fp_i, f3); np.add.at(g, fp_j, -f3)\n        m = 0.9 * m + 0.1 * g\n        v = 0.999 * v + 0.001 * (g ** 2)\n        Y -= 0.55 * (m / (1.0 - 0.9 ** it)) / (np.sqrt(v / (1.0 - 0.999 ** it)) + 1e-7)\n        Y -= Y.mean(axis=0, keepdims=True)\n    Dy = cdist(Y, Y, metric=\"euclidean\")\n    rec = float(np.mean([len(set(np.argsort(D[i])[1:11]) & set(np.argsort(Dy[i])[1:11])) / 10.0 for i in range(n)]))\n    c_hi = np.array([X[lbl == c].mean(axis=0) for c in range(4)])\n    c_lo = np.array([Y[lbl == c].mean(axis=0) for c in range(4)])\n    glob = float(spearmanr(pdist(c_hi), pdist(c_lo)).statistic)\n    # Cek apakah klaster lokal menyusut kompak vs tertarik kabur (rasio jarak antar-klaster / dalam-klaster)\n    intra = float(np.mean([np.mean(np.linalg.norm(Y[lbl == c] - c_lo[c], axis=1)) for c in range(4)]))\n    inter = float(np.mean(pdist(c_lo)))\n    return rec, glob, inter / max(intra, 1e-9)\n\nprint(\"=== 1. Ablasi 3-Fase PaCMAP (Mulai dari Inisialisasi Acak Murni!) ===\")\nprint(\"Konfigurasi PaCMAP               | 10-NN Rec | Glob Centroid | Rasio Inter/Intra\")\nprint(\"-\" * 82)\nfor label, m in [\n    (\"Full 3-Phase (w_MN: 1000->3->0)\", \"full_3phase\"),\n    (\"Tanpa Mid-Near (w_MN = 0)\", \"no_mid_near\"),\n    (\"Mid-Near Tetap (w_MN = 600)\", \"constant_mid_near\"),\n]:\n    rec, glob, sep = run_pacmap_ablation(m)\n    print(f\"{label:32s} | {rec:9.4f} | {glob:13.4f} | {sep:17.2f}x\")\n\n# 2) Audit Konektivitas Graf Fuzzy UMAP terhadap n_neighbors pada 4 Klaster Terpisah\nprint(\"\\n=== 2. Audit Konektivitas Graf Fuzzy UMAP terhadap n_neighbors ===\")\nfor k in [5, 15, 40]:\n    A = np.zeros((n, n))\n    for i in range(n):\n        nn = np.argsort(D[i])[1 : k + 1]\n        A[i, nn] = 1.0\n    A_sym = np.maximum(A, A.T)\n    n_cc, _ = connected_components(A_sym, directed=False)\n    cross_cluster = int(np.sum(A_sym[lbl[:, None] != lbl[None, :]]) // 2)\n    print(f\"n_neighbors={k:2d} | Komponen Terhubung = {n_cc} | Tepi Jembatan Antar-Klaster = {cross_cluster:4d}\")",
          "expectedOutput": "=== 1. Ablasi 3-Fase PaCMAP (Mulai dari Inisialisasi Acak Murni!) ===\nKonfigurasi PaCMAP               | 10-NN Rec | Glob Centroid | Rasio Inter/Intra\n----------------------------------------------------------------------------------\nFull 3-Phase (w_MN: 1000->3->0)  |    0.5436 |        0.5429 |             19.75x\nTanpa Mid-Near (w_MN = 0)        |    0.5164 |       -0.8857 |             42.20x\nMid-Near Tetap (w_MN = 600)      |    0.4186 |        1.0000 |              6.58x\n\n=== 2. Audit Konektivitas Graf Fuzzy UMAP terhadap n_neighbors ===\nn_neighbors= 5 | Komponen Terhubung = 4 | Tepi Jembatan Antar-Klaster =    0\nn_neighbors=15 | Komponen Terhubung = 4 | Tepi Jembatan Antar-Klaster =    0\nn_neighbors=40 | Komponen Terhubung = 1 | Tepi Jembatan Antar-Klaster =  802",
          "actualOutput": "=== 1. Ablasi 3-Fase PaCMAP (Mulai dari Inisialisasi Acak Murni!) ===\nKonfigurasi PaCMAP               | 10-NN Rec | Glob Centroid | Rasio Inter/Intra\n----------------------------------------------------------------------------------\nFull 3-Phase (w_MN: 1000->3->0)  |    0.5436 |        0.5429 |             19.75x\nTanpa Mid-Near (w_MN = 0)        |    0.5164 |       -0.8857 |             42.20x\nMid-Near Tetap (w_MN = 600)      |    0.4186 |        1.0000 |              6.58x\n\n=== 2. Audit Konektivitas Graf Fuzzy UMAP terhadap n_neighbors ===\nn_neighbors= 5 | Komponen Terhubung = 4 | Tepi Jembatan Antar-Klaster =    0\nn_neighbors=15 | Komponen Terhubung = 4 | Tepi Jembatan Antar-Klaster =    0\nn_neighbors=40 | Komponen Terhubung = 1 | Tepi Jembatan Antar-Klaster =  802",
