          "filename": "20_4_trustworthiness_continuity_shepard_scratch.py",
          "code": "import numpy as np\nfrom scipy.spatial.distance import cdist, pdist\nfrom scipy.stats import spearmanr\nfrom sklearn.datasets import make_s_curve\nfrom sklearn.decomposition import PCA\nfrom sklearn.manifold import Isomap, TSNE, trustworthiness as sk_trustworthiness\n\ndef audit_projection_scratch(X_hi: np.ndarray, Y_lo: np.ndarray, k: int = 12):\n    n = X_hi.shape[0]\n    D_hi = cdist(X_hi, X_hi, metric=\"euclidean\")\n    D_lo = cdist(Y_lo, Y_lo, metric=\"euclidean\")\n\n    # Peringkat jarak (0 = diri sendiri, 1..n-1 = tetangga terurut)\n    ord_hi = np.argsort(D_hi, axis=1)\n    ord_lo = np.argsort(D_lo, axis=1)\n    rank_hi = np.empty_like(ord_hi)\n    rank_lo = np.empty_like(ord_lo)\n    rows = np.arange(n)[:, None]\n    rank_hi[rows, ord_hi] = np.arange(n)[None, :]\n    rank_lo[rows, ord_lo] = np.arange(n)[None, :]\n\n    norm = 2.0 / (n * k * (2 * n - 3 * k - 1))\n    pen_t = 0.0\n    pen_c = 0.0\n    recalls = []\n    for i in range(n):\n        nn_hi = set(ord_hi[i, 1 : k + 1].tolist())\n        nn_lo = set(ord_lo[i, 1 : k + 1].tolist())\n        # False neighbors U_k(i): masuk k-NN 2D tapi bukan k-NN asli -> penalti r_hi(i,j) - k\n        for j in (nn_lo - nn_hi):\n            pen_t += float(rank_hi[i, j] - k)\n        # Missing neighbors V_k(i): masuk k-NN asli tapi hilang dari k-NN 2D -> penalti r_lo(i,j) - k\n        for j in (nn_hi - nn_lo):\n            pen_c += float(rank_lo[i, j] - k)\n        recalls.append(len(nn_hi & nn_lo) / float(k))\n\n    T_val = 1.0 - norm * pen_t\n    C_val = 1.0 - norm * pen_c\n    shep = float(spearmanr(pdist(X_hi), pdist(Y_lo)).statistic)\n    return T_val, C_val, float(np.mean(recalls)), shep\n\n# S-Curve 3D ber-tinggi sedang: PCA melipat dua lengkungan S saling tumpang-tindih!\nX_curve, _ = make_s_curve(n_samples=260, noise=0.04, random_state=42)\nX_curve[:, 1] *= 2.8  # Sumbu tinggi dominan -> PCA(2) memproyeksikan dari samping & melipat huruf S!\nprojs = [\n    (\"PCA (Melipat S-Curve!)\", PCA(n_components=2, random_state=42).fit_transform(X_curve)),\n    (\"Isomap (k=8, Geodesik)\", Isomap(n_neighbors=8, n_components=2).fit_transform(X_curve)),\n    (\"t-SNE (perplexity=8)\", TSNE(n_components=2, perplexity=8, init=\"pca\", learning_rate=\"auto\", max_iter=450, random_state=42).fit_transform(X_curve)),\n    (\"t-SNE (perplexity=30)\", TSNE(n_components=2, perplexity=30, init=\"pca\", learning_rate=\"auto\", max_iter=450, random_state=42).fit_transform(X_curve)),\n]\n\nprint(\"=== Audit Kuantitatif Distorsi Proyeksi From Scratch pada S-Curve 3D (k=12) ===\")\nprint(\"Metode                   | Trust T(12) | Cont C(12) | k-NN Rec | Shepard | |T - sk_T|\")\nprint(\"-\" * 86)\nfor name, Y in projs:\n    T_s, C_s, rec, shep = audit_projection_scratch(X_curve, Y, k=12)\n    T_sk = float(sk_trustworthiness(X_curve, Y, n_neighbors=12))\n    print(f\"{name:24s} | {T_s:11.4f} | {C_s:10.4f} | {rec:8.4f} | {shep:7.4f} | {abs(T_s - T_sk):.1e}\")",
          "expectedOutput": "=== Audit Kuantitatif Distorsi Proyeksi From Scratch pada S-Curve 3D (k=12) ===\nMetode                   | Trust T(12) | Cont C(12) | k-NN Rec | Shepard | |T - sk_T|\n--------------------------------------------------------------------------------------\nPCA (Melipat S-Curve!)   |      0.9623 |     0.9893 |   0.6314 |  0.9823 | 0.0e+00\nIsomap (k=8, Geodesik)   |      0.9989 |     0.9986 |   0.9125 |  0.8378 | 0.0e+00\nt-SNE (perplexity=8)     |      0.9945 |     0.9908 |   0.8035 |  0.8757 | 0.0e+00\nt-SNE (perplexity=30)    |      0.9986 |     0.9969 |   0.9038 |  0.8323 | 0.0e+00",
          "actualOutput": "=== Audit Kuantitatif Distorsi Proyeksi From Scratch pada S-Curve 3D (k=12) ===\nMetode                   | Trust T(12) | Cont C(12) | k-NN Rec | Shepard | |T - sk_T|\n--------------------------------------------------------------------------------------\nPCA (Melipat S-Curve!)   |      0.9623 |     0.9893 |   0.6314 |  0.9823 | 0.0e+00\nIsomap (k=8, Geodesik)   |      0.9989 |     0.9986 |   0.9125 |  0.8378 | 0.0e+00\nt-SNE (perplexity=8)     |      0.9945 |     0.9908 |   0.8035 |  0.8757 | 0.0e+00\nt-SNE (perplexity=30)    |      0.9986 |     0.9969 |   0.9038 |  0.8323 | 0.0e+00",
          "explanation": "Mengimplementasikan Trustworthiness dan Continuity lengkap dari nol hingga presisi 0.0e+00 identik dengan sklearn.manifold.trustworthiness, lalu membedah tanda lipatan PCA vs unfolding Isomap & t-SNE pada S-Curve 3D.",
